// 1) Install Carbon v9 and the Security Add-ons:
//    npm install carbon-components@^9 carbon-components-react@^9 carbon-addons-security react react-dom

// 2) Create src/index.js with the following:
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.css';
// If you have the add-ons installed, import the DataTablePagination wrapper:
import DataTablePagination from 'carbon-addons-security/src/components/DataTablePagination';
// If you don’t have that helper component, you can import the core Pagination directly:
// import { Pagination } from 'carbon-components-react';

const headers = [
  { key: 'id', header: 'ID' },
  { key: 'name', header: 'Name' },
  { key: 'status', header: 'Status' },
];

// Generate 650 rows so that at 10 items / page you end up with 65 pages
const rows = Array.from({ length: 650 }, (_, idx) => ({
  id: `${idx + 1}`,
  name: `Item ${idx + 1}`,
  status: 'Active',
}));

function App() {
  return (
    <div style={{ padding: '2rem', height: '100vh', overflow: 'auto' }}>
      {/* Using the security add-ons DataTablePagination: */}
      <DataTablePagination
        rows={rows}
        headers={headers}
        // fix the pageSizes to only 10 so user cannot change items per page
        pageSizes={[10]}
        pageSize={10}
      />

      {/* Or, to reproduce with vanilla Carbon v9 Pagination: */}
      {/*
      <Pagination
        backwardText="Previous page"
        forwardText="Next page"
        itemsPerPageText="Items per page:"
        page={1}
        pageSize={10}
        pageSizes={[10]}
        totalItems={650}
        onChange={({ page }) => console.log('go to page', page)}
      />
      */}
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
